/* Google Scholar citation visualization. The data file is generated by GitHub Actions. */
(async function () {
  const cumulativeSvg = document.getElementById('cumulative-svg');
  const publicationsSvg = document.getElementById('publications-svg');
  const note = document.getElementById('citation-updated');
  const tooltip = document.getElementById('citation-tooltip');
  const details = document.getElementById('citation-details');
  const ns = 'http://www.w3.org/2000/svg';
  function element(svg, tag, attrs, text) {
    const n = document.createElementNS(ns, tag);
    Object.entries(attrs).forEach(([k, v]) => n.setAttribute(k, String(v)));
    if (text !== undefined) n.textContent = text;
    svg.appendChild(n);
    return n;
  }
  function show(group) {
    tooltip.replaceChildren();
    group.forEach(p => {
      const title = document.createElement('strong');
      title.textContent = p.title;
      tooltip.append(title);
    });
    tooltip.hidden = false;
  }
  function select(group) {
    details.replaceChildren();
    group.forEach(p => {
      const item = document.createElement('p');
      if (p.link && /^https:\/\/(scholar\.google\.com|doi\.org)\//.test(p.link)) {
        const a = document.createElement('a');
        a.href = p.link;
        a.textContent = p.title + ' ↗';
        a.target = '_blank';
        a.rel = 'noopener noreferrer';
        item.append(a);
      } else {
        item.textContent = p.title;
      }
      details.append(item);
    });
  }
  try {
    const response = await fetch('data/citations.json', {cache: 'no-cache'});
    if (!response.ok) throw new Error('data unavailable');
    const d = await response.json();
    const papers = d.publications.filter(p => Number.isInteger(p.year));
    const annual = [...d.annual].sort((a,b) => a.year-b.year);
    if (!papers.length || !annual.length) throw new Error('data unavailable');
    function renderAxes(svg, years, maxValue, xLabel) {
      const lo = years[0], hi = years[years.length - 1];
      const x = year => 90 + (year - lo) / Math.max(1, hi - lo) * 700;
      const y = value => 255 - value / maxValue * 205;
      // Use citation ticks in multiples of ten and keep the upper bound visible.
      const step = Math.max(10, Math.ceil(maxValue / 50) * 10);
      const ticks = [];
      for (let value = 0; value < maxValue; value += step) ticks.push(value);
      ticks.push(maxValue);
      ticks.forEach(value => {
        const yy = y(value);
        if (value > 0 && value < maxValue) {
          element(svg, 'line', {x1:90,y1:yy,x2:790,y2:yy,class:'chart-grid'});
        }
        element(svg, 'text', {x:76,y:yy+4,'text-anchor':'end',class:'chart-tick'}, String(value));
      });
      element(svg, 'rect', {x:90,y:50,width:700,height:205,class:'chart-frame'});
      years.forEach(year => element(svg, 'text', {x:x(year),y:282,'text-anchor':'middle',class:'chart-tick'}, String(year)));
      element(svg, 'text', {x:440,y:315,'text-anchor':'middle',class:'chart-tick'}, xLabel);
      return {x,y};
    }

    // Cumulative values are based on citations received in each calendar year.
    let sum = 0;
    const totals = annual.map(a => ({year:a.year, annual:a.citations, total:sum += a.citations}));
    const cumulativeMax = (Math.floor(sum / 10) + 1) * 10;
    const cumulative = renderAxes(cumulativeSvg, totals.map(a => a.year), cumulativeMax, 'Citation year');
    element(cumulativeSvg, 'polyline', {
      points:totals.map(a => `${cumulative.x(a.year)},${cumulative.y(a.total)}`).join(' '), class:'chart-line'
    });
    totals.forEach(a => {
      const point = element(cumulativeSvg, 'circle', {cx:cumulative.x(a.year),cy:cumulative.y(a.total),r:4.5,class:'chart-dot'});
      const tip = document.createElementNS(ns, 'title');
      tip.textContent = `${a.year}: ${a.annual} citations; cumulative ${a.total}`;
      point.appendChild(tip);
    });

    // Publications with matching year and citation count share a bubble.
    const years = [...new Set(papers.map(p => p.year))].sort((a,b) => a-b);
    const maxCitations = Math.max(0, ...papers.map(p => p.citations));
    const publicationMax = (Math.floor(maxCitations / 10) + 1) * 10;
    const plot = renderAxes(publicationsSvg, years, publicationMax, 'Publication year');
    const group = new Map();
    papers.forEach(p => {
      const key = `${p.year}:${p.citations}`;
      const matching = group.get(key) || [];
      matching.push(p);
      group.set(key, matching);
    });
    for (const same of group.values()) {
      const p = same[0];
      const c = element(publicationsSvg, 'circle', {
        cx:plot.x(p.year), cy:plot.y(p.citations), r:8, class:'chart-bubble',
        tabindex:0, role:'button',
        'aria-label':`${same.length} publication${same.length === 1 ? '' : 's'}, ${p.year}, ${p.citations} citations: ${same.map(item => item.title).join('; ')}`
      });
      c.addEventListener('mouseenter',()=>show(same));
      c.addEventListener('mouseleave',()=>{tooltip.hidden=true});
      c.addEventListener('focus',()=>show(same));
      c.addEventListener('blur',()=>{tooltip.hidden=true});
      c.addEventListener('click',()=>select(same));
      c.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(same)}});
    }
    const missing=d.publications.length-papers.length;
    const date=new Date(d.updated_at).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
    note.textContent=`Source: ${d.source} · Updated ${date} · ${d.publications.length} entries · ${d.total_citations} total citations${missing ? ` · ${missing} entries without a publication year are not plotted` : ''}. The current year is incomplete; previous years reflect the latest index.`;
  } catch (_) {
    note.textContent='Citation data is temporarily unavailable. Please visit Google Scholar for the latest information.';
  }
})();
